files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #1a56c7;
  --vt-accent-on-deep: #96b8ff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  position: relative;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: all 0.3s;
}

.root a:hover {
  color: var(--vt-accent-ink);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--vt-surface);
  box-shadow: 0 2px 15px rgba(0, 0, 0, 0.1);
  z-index: 1000;
}

.navIn {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
  max-width: 1140px;
  margin: 0 auto;
  padding: 15px 15px;
}

.logo {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.brand {
  display: block;
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--vt-accent);
}

.navLinks {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
}

.navLinks a {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--vt-ink-soft);
  padding: 0.25rem 0.5rem;
  white-space: nowrap;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

/* Hero */
.hero {
  position: relative;
  margin-top: 74px;
  overflow: hidden;
}

.heroSlider {
  width: 100%;
  max-height: 580px;
  overflow: hidden;
}

.sliderTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.sliderTrack::-webkit-scrollbar {
  display: none;
}

.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  margin: 0;
}

.slide img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
  max-height: 580px;
}

@media (prefers-reduced-motion: reduce) {
  .sliderTrack {
    scroll-behavior: auto;
  }
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 2rem;
  box-shadow: 0 0 30px rgba(0,0,0,0.1);
}

.heroText h1 {
  font-size: 3rem;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
  line-height: 1.2;
}

.heroText p {
  color: var(--vt-ink-soft);
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent-ink);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  font-size: 0.9rem;
  transition: all 0.3s;
  background: transparent;
  cursor: pointer;
}

.customLink:hover {
  background: var(--vt-surface-2);
  border-color: var(--vt-accent-ink);
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  font-size: 1rem;
}

/* About */
.aboutRow {
  display: flex;
  justify-content: center;
}

.aboutContent {
  max-width: 800px;
  width: 100%;
}

.aboutContent h2 {
  font-size: 2.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--vt-ink);
}

.aboutContent p {
  color: var(--vt-ink-soft);
  font-size: 1.1rem;
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

/* Gallery */
.gallery {
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
  margin: 0;
}

.galleryItem {
  flex: 0 0 50%;
  position: relative;
  overflow: hidden;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.gallerySub {
  position: absolute;
  bottom: 10px;
  left: 10px;
  background: rgba(0,0,0,0.6);
  color: #fff;
  padding: 2px 8px;
  font-size: 0.8rem;
  border-radius: 3px;
}

/* Timeline */
.timelineTitle {
  text-align: center;
  margin-bottom: 3rem;
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  margin-bottom: 3rem;
  position: relative;
}

.timelineNode:last-child {
  margin-bottom: 0;
}

.timelineContent {
  flex: 1;
  max-width: 45%;
  background: var(--vt-surface);
  box-shadow: 0 0 20px rgba(0,0,0,0.08);
  border-radius: 0.25rem;
  position: relative;
  z-index: 2;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  font-size: 1.25rem;
  margin: 0;
}

.timelineContent p {
  color: var(--vt-ink-soft);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0 0 0.25rem 0.25rem;
  font-size: 0.95rem;
  line-height: 1.6;
}

.timelineIcon {
  flex: 0 0 80px;
  height: 80px;
  width: 80px;
  margin: 0 auto;
  position: relative;
  z-index: 3;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0,0,0,.175);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: bold;
  color: var(--vt-accent);
}

.timelineIcon span {
  line-height: 1;
}

.timelineDate {
  flex: 1;
  max-width: 30%;
  padding: 1rem 0;
  box-sizing: border-box;
}

.timelineDate time {
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
  font-weight: 600;
}

/* Alternate sides */
.timelineNode:nth-child(odd) {
  flex-direction: row;
}

.timelineNode:nth-child(odd) .timelineContent h3,
.timelineNode:nth-child(odd) .timelineContent p {
  text-align: right;
}

.timelineNode:nth-child(odd) .timelineDate {
  text-align: left;
}

.timelineNode:nth-child(odd) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) {
  flex-direction: row-reverse;
}

.timelineNode:nth-child(even) .timelineContent h3,
.timelineNode:nth-child(even) .timelineContent p {
  text-align: left;
}

.timelineNode:nth-child(even) .timelineDate {
  text-align: right;
}

.timelineNode:nth-child(even) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* Footer */
.footer {
  background: var(--vt-surface-2);
  padding: 4rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerCol {
  flex: 1 1 200px;
  min-width: 180px;
}

.footerCol h5 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--vt-ink);
}

.hoursList {
  list-style: none;
  padding: 0;
  margin: 0;
}

.hoursList li {
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--vt-line);
  color: var(--vt-ink-soft);
  font-size: 0.95rem;
}

.hoursList li:last-child {
  border-bottom: none;
}

.copyright {
  font-size: 0.85rem;
  color: var(--vt-ink-soft);
}

/* Responsive */
@media (max-width: 991px) {
  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .hero {
    margin-top: 50px;
  }

  .heroText {
    position: relative;
    bottom: auto;
    right: auto;
    width: auto;
    margin-top: -100px;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .heroText h1 {
    font-size: 2.5rem;
  }

  .timelineNode {
    flex-direction: column !important;
    align-items: flex-start;
  }

  .timelineContent {
    max-width: 100%;
    width: 100%;
    margin-left: 0;
    margin-right: 0;
  }

  .timelineContent h3,
  .timelineContent p {
    text-align: left !important;
  }

  .timelineContent h3::after {
    display: none;
  }

  .timelineIcon {
    position: absolute;
    left: 20px;
    top: 20px;
    width: 60px;
    height: 60px;
    flex-basis: 60px;
    font-size: 1.5rem;
  }

  .timelineDate {
    max-width: 100%;
    width: 100%;
    text-align: left !important;
    padding: 0.5rem 0 0 90px;
  }

  .timeline::before {
    left: 50px;
    top: 45px;
    height: 90%;
  }
}

@media (max-width: 767px) {
  .navIn {
    padding: 10px;
    gap: 0.25rem;
  }

  .navLinks {
    gap: 0.5rem;
    font-size: 0.85rem;
  }

  .navLinks a {
    padding: 0.25rem 0.25rem;
  }

  .heroText {
    padding: 1.5rem;
  }

  .heroText h1 {
    font-size: 2rem;
  }

  .heroText p {
    font-size: 1rem;
  }

  .customLink {
    font-size: 0.8rem;
    line-height: 35px;
    padding: 0 20px;
  }

  .contactPhone {
    font-size: 0.9rem;
  }

  .aboutContent h2 {
    font-size: 1.8rem;
  }

  .galleryItem {
    flex: 0 0 100%;
  }

  .timelineTitle {
    font-size: 1.8rem;
  }

  .timelineIcon {
    left: 15px;
    top: 15px;
    width: 50px;
    height: 50px;
    flex-basis: 50px;
    font-size: 1.2rem;
  }

  .timeline::before {
    left: 40px;
  }

  .timelineDate {
    padding-left: 75px;
  }

  .footerRow {
    gap: 1.5rem;
  }
}

@media (max-width: 480px) {
  .navLinks a {
    font-size: 0.8rem;
  }

  .heroText {
    padding: 1rem;
  }

  .heroText h1 {
    font-size: 1.6rem;
  }

  .customLink {
    font-size: 0.75rem;
    line-height: 30px;
    padding: 0 15px;
  }

  .contactPhone {
    font-size: 0.8rem;
  }

  .timelineIcon {
    left: 10px;
    top: 10px;
    width: 40px;
    height: 40px;
    flex-basis: 40px;
    font-size: 1rem;
  }

  .timeline::before {
    left: 30px;
  }

  .timelineDate {
    padding-left: 60px;
  }
}
